add_filter( 'comment_text', 'perfectpixel_collapse_long_comments', 50 );
add_action( 'wp_footer', 'perfectpixel_collapse_long_comments_script' );

function perfectpixel_collapse_long_comments( $text ) {
	if ( is_admin() || is_feed() || mb_strlen( wp_strip_all_tags( $text ) ) <= max( 100, (int) '{{comment_collapse_chars}}' ) ) {
		return $text;
	}
	return '<div class="perfectpixel-long-comment" style="max-height:9em;overflow:hidden;-webkit-mask-image:linear-gradient(#000 60%,transparent);mask-image:linear-gradient(#000 60%,transparent)">' . $text . '</div><a href="#" class="perfectpixel-comment-toggle">' . esc_html( '{{comment_more_text}}' ) . '</a>';
}

function perfectpixel_collapse_long_comments_script() {
	if ( ! is_singular() ) {
		return;
	}
	$labels = array( 'more' => '{{comment_more_text}}', 'less' => '{{comment_less_text}}' );
	?>
	<script>
	document.addEventListener( 'click', function ( e ) {
		var link = e.target.closest( '.perfectpixel-comment-toggle' );
		if ( ! link ) {
			return;
		}
		e.preventDefault();
		var labels = <?php echo wp_json_encode( $labels ); ?>;
		var box    = link.previousElementSibling;
		var open   = 'none' === box.style.maxHeight;
		box.style.maxHeight       = open ? '9em' : 'none';
		box.style.webkitMaskImage = box.style.maskImage = open ? 'linear-gradient(#000 60%,transparent)' : 'none';
		link.textContent          = open ? labels.more : labels.less;
	} );
	</script>
	<?php
}
